// Generated by `cargo xtask gen` from the tool's Rust output types. Do not edit.

export type Slot = "A" | "B";

export type SlotView = {
	slot: Slot;
	/**
	 * The entry file, relative to the ESP (`loader/entries/<prefix>-a.conf`).
	 */
	entry: string;
	/**
	 * The directory of its kernel and initramfs, relative to the ESP.
	 */
	boot_dir: string;
	/**
	 * The entry's `root=` (`PARTUUID=...`), if it has one.
	 */
	root: string | null;
	/**
	 * The block device `root` names on this machine, if present.
	 */
	device: string | null;
	/**
	 * Every file the entry loads is on the ESP.
	 */
	bootable: boolean;
	/**
	 * The entry carries a trial's options (it was staged or scheduled and
	 * not yet committed).
	 */
	trial: boolean;
};

export type Status = {
	active_slot: Slot;
	inactive_slot: Slot;
	/**
	 * A one-shot trial boot is set in the firmware and not yet taken.
	 */
	trial_pending: boolean;
	/**
	 * The slot the next boot starts: the trial slot, else the default.
	 */
	next_boot: Slot | null;
	default_slot: Slot | null;
	known_good_slot: Slot | null;
	/**
	 * The running slot is the known-good slot. After a trial boot this is
	 * false until it is committed; an uncommitted slot is left on next boot.
	 */
	committed: boolean;
	/**
	 * The slot `recab rollback` would select, if any.
	 */
	rollback_slot: Slot | null;
	/**
	 * How the last judged trial boot ended.
	 */
	last_trial: TrialRecord | null;
	entry_prefix: string;
	/**
	 * Each slot's entry, kernel directory and partition.
	 */
	slots: Array<SlotView>;
};

export type TrialRecord = {
	slot: Slot;
	/**
	 * The trial was healthy and committed; otherwise it was abandoned.
	 */
	committed: boolean;
	/**
	 * How startup ended, and the failed units if any.
	 */
	detail: string;
	unix_time: number;
};

export type Health = {
	init: InitSystem;
	/**
	 * How startup ended.
	 */
	startup: Startup;
	/**
	 * Startup ran to its end, healthy or not (`startup` is `running` or
	 * `failed`).
	 */
	finished: boolean;
	/**
	 * The init's own word: systemd's `is-system-running` answer, OpenRC's
	 * softlevel, or `timed out`.
	 */
	state: string;
	/**
	 * The units or services that failed (and, on OpenRC, crashed daemons),
	 * sorted, by bare name; listed even when startup did not finish.
	 */
	failed: Array<string>;
};

export type InitSystem = "systemd" | "openrc";

export type Startup = "running" | "failed" | "emergency" | "timed_out" | "inconclusive";

export type ErrorClass =
	| "permission"
	| "backend_unavailable"
	| "state_or_detection"
	| "partial_update"
	| "trial_failed";

export type ErrorPayload = {
	schema_version: number;
	/**
	 * `None` for an error without a class (exit status 1).
	 */
	class: ErrorClass | null;
	/**
	 * The exit status.
	 */
	code: number;
	message: string;
};

